     * Scopes: team:update.
     *
     * @param  DateTimeInterface|string|null  $startsAt  Default: now
     * @param  DateTimeInterface|string|null  $endsAt  null = until switched off
     * @param  ?string  $note  Internal reason, never sent to customers
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Users/create_member_absence_api_v1_users__user_id__absences_post
     */
    public function createMemberAbsence(
        string $userId,
        ?string $substituteMode = null,
        ?string $substituteUserId = null,
        ?string $substituteInboxId = null,
        ?string $substituteTagId = null,
        DateTimeInterface|string|null $startsAt = null,
        DateTimeInterface|string|null $endsAt = null,
        ?string $note = null,
        ?string $idempotencyKey = null,
    ): Absence {
        $response = $this->connector->send(new Request(
            Method::Post,
