    /**
     * Set Account Billing Access.
     *
     * Grant or revoke account-wide usage access for a team member.
     *
     * Idempotently grants (enabled=true) or revokes (enabled=false) a DIRECT account:billing_read
     * scope on the target user within the current workspace. This is the backing endpoint for the "Can
     * view account-wide usage" checkbox on /settings/team.
     *
     * OWNER-ONLY: only the OWNER of the billing account that owns the current workspace may toggle
     * this — enforced by the same Part B owner-guard used on every account:billing_read grant path
     * (_enforce_owner_for_account_billing_scope). The billing account is always derived server-side
     * from the authenticated tenant; never caller-supplied. Fail-closed: a non-owner (or any missing
     * row) gets 403.
     *
     * Scopes: team:admin.
     *
     * @param  bool  $enabled  True grants the member a direct `account:billing_read` scope; False revokes it
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Users/set_account_billing_access_api_v1_users__user_id__account_billing_access_put
     */
    public function setAccountBillingAccess(string $userId, bool $enabled): AccountBillingAccess
    {
        $response = $this->connector->send(new Request(
            Method::Put,
            '/users/'.Payload::segment($userId).'/account-billing-access',
            body: Payload::body(['enabled' => $enabled]),
        ));

        return AccountBillingAccess::fromArray($response->data());
    }

