     *
     * @param  array<string, mixed>|null  $workSchedule
     * @param  ?string  $autoReplyAbsenceText  Auto-reply text. Variables: {{agent.name}}, {{agent.first_name}}, {{agent.substitute_name}}, {{agent.return_date}}, {{agent.next_shift}} and the standard contact variables ({{contact.first_name}}, {{contact.custom.<key>}}, ...). Unresolved variables render empty.
     * @param  array<string, mixed>|null  $autoReplyAbsenceTranslations
     * @param  ?string  $autoReplyOffHoursText  Auto-reply text. Variables: {{agent.name}}, {{agent.first_name}}, {{agent.substitute_name}}, {{agent.return_date}}, {{agent.next_shift}} and the standard contact variables ({{contact.first_name}}, {{contact.custom.<key>}}, ...). Unresolved variables render empty.
     * @param  array<string, mixed>|null  $autoReplyOffHoursTranslations
     * @param  list<string>|null  $autoReplyExcludedChannelTypes
     * @param  array<string, mixed>|null  $defaultSubstitute
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Users/put_member_availability_api_v1_users__user_id__availability_put
     */
    public function putMemberAvailability(
        string $userId,
        ?string $timezone = null,
        ?bool $workScheduleEnabled = null,
        ?array $workSchedule = null,
        ?bool $autoReplyAbsenceEnabled = null,
        ?string $autoReplyAbsenceText = null,
        ?array $autoReplyAbsenceTranslations = null,
        ?bool $autoReplyOffHoursEnabled = null,
        ?string $autoReplyOffHoursText = null,
        ?array $autoReplyOffHoursTranslations = null,
        ?array $autoReplyExcludedChannelTypes = null,
        ?array $defaultSubstitute = null,
    ): AvailabilitySettings {
        $response = $this->connector->send(new Request(
            Method::Put,
            '/users/'.Payload::segment($userId).'/availability',
            body: Payload::body([
                'timezone' => $timezone,
                'work_schedule_enabled' => $workScheduleEnabled,
                'work_schedule' => $workSchedule,
                'auto_reply_absence_enabled' => $autoReplyAbsenceEnabled,
                'auto_reply_absence_text' => $autoReplyAbsenceText,
                'auto_reply_absence_translations' => $autoReplyAbsenceTranslations,
                'auto_reply_off_hours_enabled' => $autoReplyOffHoursEnabled,
                'auto_reply_off_hours_text' => $autoReplyOffHoursText,
                'auto_reply_off_hours_translations' => $autoReplyOffHoursTranslations,
                'auto_reply_excluded_channel_types' => $autoReplyExcludedChannelTypes,
                'default_substitute' => $defaultSubstitute,
            ]),
        ));

        return AvailabilitySettings::fromArray($response->data());
    }

    /**
     * Update Team Membership.
     *
     * Update a team member's per-workspace settings.
     *
     * Currently one setting: ai_suggestions_enabled ("Can use AI suggestions in Conversations"). When
     * false, the member cannot use AI drafting, AI suggestions, AI instructions or manual summaries in
     * Conversations in this workspace. Translation stays available. Default is true for every member.
     *
     * PATCH semantics: omitted (or null) fields stay unchanged; a body that sets nothing returns 422.
