            '/users/'.Payload::segment($userId).'/membership',
            body: Payload::body(['ai_suggestions_enabled' => $aiSuggestionsEnabled]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return TeamMembership::fromArray($response->data());
    }

